// Generated C stack frames must not grow with function body length: every
// packed operation writes its result through a destination pointer instead of
// returning a descriptor through a per-call-site stack temporary. Both
// functions run the same statement; body_long repeats it 128 times.
module tb;
    function automatic logic [127:0] body_short(input logic [127:0] x, input integer n);
        logic [127:0] a, b;
        a = x; b = x + 1;
        b = (a + x) ^ (b * a); a = b - {4{n}};
        return a ^ b;
    endfunction

